"    // Check if it's a pre-order (POS Order has pre_order_id, DB object has advance_paid and status != 'COMPLETED')
    const isPreOrder = !!(order.pre_order_id || (order.advance_paid !== undefined && order.status !== 'COMPLETED'));

    // Determine copies to print
    const copiesToPrint = [];
    if (isPreOrder) {
      if (posSettings.printCustomerCopyPreorder !== false) {
        copiesToPrint.push('CUSTOMER COPY');
      }
      if (posSettings.printRestaurantCopyPreorder !== false) {
        copiesToPrint.push('RESTAURANT COPY');
      }
      if (copiesToPrint.length === 0) {
        copiesToPrint.push(''); // Default fallback if both toggles are turned off
      }
    } else {
      copiesToPrint.push('');
    }"
